    """
    Convert a 1D, non-pandas sequence to a range if possible.

    Returns the input if not possible.

    Parameters
    ----------
    sequence : 1D sequence
    names : sequence of str

    Returns
    -------
    Any : input or range
    """
    if isinstance(sequence, (ABCSeries, Index)):
        return sequence
    np_sequence = np.asarray(sequence)
    n = len(np_sequence)
    if np_sequence.dtype.kind != "i" or n == 1:
        return sequence
    elif n == 0:
        return range(0)
    start = np_sequence[0]
    diff = np_sequence[1] - start
    if diff == 0:
        return sequence
    elif n == 2:
        return range(start, np_sequence[1] + diff, diff)

    # Fast path for common case (step=1)
    if diff == 1:
        # Check if this could be a range: sorted, no duplicates, complete coverage
        # First element is n unique values
        if np_sequence[-1] - start + 1 == n:
            # Could be a range, verify with sortedness check
            # Sort a copy (we don't want to modify original) and compare
            # For random data this often fails early
            if np_sequence[-1] > np_sequence[0]:
                # Check sortedness using difference from expected values
                # This avoids creating a full arange array
                expected = np.arange(start, start + n)
                if np.array_equal(np_sequence, expected):
                    return range(start, np_sequence[-1] + 1)
        return sequence

    # General case: use divmod to check if all elements fit the pattern
    maybe_range_indexer, remainder = np.divmod(np_sequence - start, diff)
    if (
        lib.is_range_indexer(maybe_range_indexer, n)
        and not remainder.any()
    ):
        return range(start, np_sequence[-1] + diff, diff)
    return sequence

